package pe.edu.lab16.eventos;
import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import jakarta.validation.Valid;import java.util.List;
@RestController @RequestMapping("/eventos") public class EventoController{private final EventoService s;public EventoController(EventoService s){this.s=s;}@GetMapping public List<Evento> listar(){return s.listar();}@GetMapping("/{id}") public Evento obtener(@PathVariable Long id){return s.obtener(id);}@PostMapping public ResponseEntity<Evento> crear(@Valid @RequestBody EventoRequest r){return ResponseEntity.status(201).body(s.crear(r));}@PutMapping("/{id}") public Evento actualizar(@PathVariable Long id,@Valid @RequestBody EventoRequest r){return s.actualizar(id,r);}@DeleteMapping("/{id}") public ResponseEntity<Void> eliminar(@PathVariable Long id){s.eliminar(id);return ResponseEntity.noContent().build();}}
